/* Common identity bytes only: no file I/O, coverage or authority provider. */
#ifdef FRONTEND
#include "postgres_fe.h"
#else
#include "postgres.h"
#endif
#include "cluster/cluster_recovery_format.h"
#include "port/pg_crc32c.h"
#include "unit_test.h"

UT_DEFINE_GLOBALS();

/* C byte table, CRC independently generated by a bitwise Castagnoli fixture. */
static const uint8 golden[128] = {
	0x52, 0x46, 0x49, 0x32, 0x00, 0x02, 0x00, 0x80, 0x00, 0x03, 0x00, 0x7f, 0x45, 0x31, 0x43, 0x32,
	0x00, 0x00, 0x00, 0x02, 0x01, 0x02, 0x03, 0x04, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08,
	0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27,
	0x28, 0x29, 0x2a, 0x2b, 0x2c, 0x2d, 0x2e, 0x2f, 0x30, 0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37,
	0x38, 0x39, 0x3a, 0x3b, 0x3c, 0x3d, 0x3e, 0x3f, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57, 0x58,
	0x61, 0x62, 0x63, 0x64, 0x71, 0x72, 0x73, 0x74, 0x81, 0x82, 0x83, 0x84, 0x85, 0x86, 0x87, 0x88,
	0x91, 0x92, 0x93, 0x94, 0x95, 0x96, 0x97, 0x98, 0xa1, 0xa2, 0xa3, 0xa4, 0xa5, 0xa6, 0xa7, 0xa8,
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x50, 0x8c, 0x3b, 0xb6,
};

static ClusterRecoveryFileIdentityV2
fixture(void)
{
	ClusterRecoveryFileIdentityV2 id = {0};
	id.kind = CLUSTER_RECOVERY_FILE_RELMAP_V2;
	id.origin = 127;
	id.format_id = CLUSTER_RECOVERY_FORMAT_ID_V2;
	id.format_version = CLUSTER_RECOVERY_FORMAT_VERSION_V2;
	id.system_identifier = UINT64CONST(0x0102030405060708);
	id.database_incarnation = UINT64CONST(0x1112131415161718);
	id.redo_timeline = 0x01020304;
	for (int i = 0; i < 16; i++) {
		id.storage_uuid[i] = 0x20 + i;
		id.redo_branch_uuid[i] = 0x30 + i;
	}
	id.redo_branch_generation = UINT64CONST(0x5152535455565758);
	id.database_oid = 0x61626364;
	id.tablespace_oid = 0x71727374;
	id.object_id = UINT64CONST(0x8182838485868788);
	id.creation_generation = UINT64CONST(0x9192939495969798);
	id.registration_generation = UINT64CONST(0xa1a2a3a4a5a6a7a8);
	return id;
}

static void
recrc(uint8 bytes[128])
{
	pg_crc32c crc;
	INIT_CRC32C(crc);
	COMP_CRC32C(crc, bytes, 124);
	FIN_CRC32C(crc);
	for (int i = 0; i < 4; i++) bytes[124+i] = crc >> (24-8*i);
}

UT_TEST(test_encode_matches_independent_bytes)
{
	ClusterRecoveryFileIdentityV2 id = fixture();
	uint8 out[128];
	memset(out, 0xa5, sizeof(out));
	UT_ASSERT(cluster_recovery_file_identity_encode_v2(&id, out, sizeof(out)));
	UT_ASSERT(memcmp(out, golden, sizeof(out)) == 0);
}

UT_TEST(test_decode_preserves_every_field_without_struct_padding)
{
	ClusterRecoveryFileIdentityV2 id;
	memset(&id, 0xa5, sizeof(id));
	UT_ASSERT(cluster_recovery_file_identity_decode_v2(golden, sizeof(golden), &id));
	UT_ASSERT_EQ(id.kind, CLUSTER_RECOVERY_FILE_RELMAP_V2);
	UT_ASSERT_EQ(id.origin, 127);
	UT_ASSERT_EQ(id.system_identifier, UINT64CONST(0x0102030405060708));
	UT_ASSERT_EQ(id.database_incarnation, UINT64CONST(0x1112131415161718));
	UT_ASSERT_EQ(id.redo_timeline, 0x01020304);
	UT_ASSERT_EQ(id.redo_branch_generation, UINT64CONST(0x5152535455565758));
	UT_ASSERT_EQ(id.database_oid, 0x61626364);
	UT_ASSERT_EQ(id.tablespace_oid, 0x71727374);
	UT_ASSERT_EQ(id.object_id, UINT64CONST(0x8182838485868788));
	UT_ASSERT_EQ(id.creation_generation, UINT64CONST(0x9192939495969798));
	UT_ASSERT_EQ(id.registration_generation, UINT64CONST(0xa1a2a3a4a5a6a7a8));
	UT_ASSERT(memcmp(id.storage_uuid, golden + 40, 16) == 0);
	UT_ASSERT(memcmp(id.redo_branch_uuid, golden + 56, 16) == 0);
	UT_ASSERT_EQ(id.format_id, CLUSTER_RECOVERY_FORMAT_ID_V2);
	UT_ASSERT_EQ(id.format_version, CLUSTER_RECOVERY_FORMAT_VERSION_V2);
}

UT_TEST(test_all_families_and_zero_origin_use_one_codec)
{
	for (int k = 1; k <= 4; k++) {
		ClusterRecoveryFileIdentityV2 id = fixture();
		ClusterRecoveryFileIdentityV2 out = {0};
		uint8 bytes[128];
		id.kind = (ClusterRecoveryFileKindV2) k;
		id.origin = 0;
		id.object_id = 0; /* CLOG segment zero is a real object. */
		UT_ASSERT(cluster_recovery_file_identity_encode_v2(&id, bytes, sizeof(bytes)));
		UT_ASSERT(cluster_recovery_file_identity_decode_v2(bytes, sizeof(bytes), &out));
		UT_ASSERT_EQ(out.kind, k);
		UT_ASSERT_EQ(out.origin, 0);
		UT_ASSERT_EQ(out.object_id, 0);
		UT_ASSERT(cluster_recovery_file_identity_matches_v2(bytes, sizeof(bytes), &id));
	}
}

UT_TEST(test_matches_checks_every_identity_field)
{
	/* Each is a valid identity change with a newly valid CRC. */
	const unsigned offsets[] = { 8,10,20,24,32,40,56,72,80,84,88,96,104 };
	ClusterRecoveryFileIdentityV2 expected = fixture();
	UT_ASSERT(cluster_recovery_file_identity_matches_v2(golden, sizeof(golden), &expected));
	for (unsigned i = 0; i < lengthof(offsets); i++) {
		uint8 bytes[128];
		ClusterRecoveryFileIdentityV2 out = {0};
		memcpy(bytes, golden, sizeof(bytes));
		/* origin's low byte keeps it inside the original 128-origin bound. */
		bytes[offsets[i] == 8 ? 9 : offsets[i] == 10 ? 11 : offsets[i]] ^= 1;
		recrc(bytes);
		UT_ASSERT(cluster_recovery_file_identity_decode_v2(bytes, sizeof(bytes), &out));
		UT_ASSERT(!cluster_recovery_file_identity_matches_v2(bytes, sizeof(bytes), &expected));
	}
}

UT_TEST(test_corruption_preserves_the_complete_output)
{
	ClusterRecoveryFileIdentityV2 saved;
	memset(&saved, 0xa5, sizeof(saved));
	for (unsigned i = 0; i < sizeof(golden); i++) {
		ClusterRecoveryFileIdentityV2 out;
		uint8 bytes[128];
		memcpy(&out, &saved, sizeof(out));
		memcpy(bytes, golden, sizeof(bytes));
		bytes[i] ^= 1;
		UT_ASSERT(!cluster_recovery_file_identity_decode_v2(bytes, sizeof(bytes), &out));
		UT_ASSERT(memcmp(&out, &saved, sizeof(out)) == 0);
	}
}

UT_TEST(test_recomputed_crc_does_not_accept_malformed_identity)
{
	/* Bad framing, kind, origin, assigned format/version, zeros and reserved. */
	const unsigned offsets[] = { 0,4,6,8,10,12,16,20,24,32,40,56,72,96,104,112 };
	const unsigned widths[]  = { 1,2,2,2, 2, 4, 4, 4, 8, 8,16,16, 8, 8,  8,  1 };
	for (unsigned i = 0; i < lengthof(offsets); i++) {
		ClusterRecoveryFileIdentityV2 out, saved;
		uint8 bytes[128];
		memcpy(bytes, golden, sizeof(bytes));
		memset(bytes+offsets[i], 0, widths[i]);
		if (offsets[i] == 10) bytes[11] = 128;
		if (offsets[i] == 112) bytes[112] = 1;
		recrc(bytes);
		memset(&out, 0xa5, sizeof(out)); memcpy(&saved, &out, sizeof(out));
		UT_ASSERT(!cluster_recovery_file_identity_decode_v2(bytes, sizeof(bytes), &out));
		UT_ASSERT(memcmp(&out, &saved, sizeof(out)) == 0);
	}
}

UT_TEST(test_invalid_encode_does_not_touch_destination)
{
	for (int i = 0; i < 12; i++) {
		ClusterRecoveryFileIdentityV2 id = fixture();
		uint8 out[128], saved[128];
		switch (i) {
			case 0: id.kind = CLUSTER_RECOVERY_FILE_UNKNOWN_V2; break;
			case 1: id.kind = (ClusterRecoveryFileKindV2)5; break;
			case 2: id.origin = 128; break;
			case 3: id.format_id ^= 1; break;
			case 4: id.format_version++; break;
			case 5: id.system_identifier = 0; break;
			case 6: id.database_incarnation = 0; break;
			case 7: id.creation_generation = UINT64_MAX; break;
			case 8: id.registration_generation = 0; break;
			case 9: id.redo_branch_generation = 0; break;
			case 10: id.redo_timeline = 0; break;
			case 11: memset(id.storage_uuid,0,16); break;
		}
		memset(out, 0xa5, sizeof(out)); memcpy(saved,out,sizeof(out));
		UT_ASSERT(!cluster_recovery_file_identity_encode_v2(&id,out,sizeof(out)));
		UT_ASSERT(memcmp(out,saved,sizeof(out))==0);
	}
}

UT_TEST(test_aliases_and_wrong_lengths_preserve_inputs_and_outputs)
{
	union { ClusterRecoveryFileIdentityV2 alignment; uint8 bytes[512]; } data;
	uint8 saved[512];
	ClusterRecoveryFileIdentityV2 id = fixture(), out, old;
	memset(&data,0xa5,sizeof(data)); data.alignment = id;
	memcpy(saved,data.bytes,sizeof(saved));
	UT_ASSERT(!cluster_recovery_file_identity_encode_v2(&data.alignment,data.bytes+8,128));
	UT_ASSERT(memcmp(data.bytes,saved,sizeof(saved))==0);
	memcpy(data.bytes,golden,128); memcpy(saved,data.bytes,sizeof(saved));
	UT_ASSERT(!cluster_recovery_file_identity_decode_v2(data.bytes,128,
		(ClusterRecoveryFileIdentityV2 *)(void *)(data.bytes+8)));
	UT_ASSERT(!cluster_recovery_file_identity_matches_v2(data.bytes,128,
		(const ClusterRecoveryFileIdentityV2 *)(const void *)(data.bytes+8)));
	UT_ASSERT(memcmp(data.bytes,saved,sizeof(saved))==0);
	memset(&out,0xa5,sizeof(out)); memcpy(&old,&out,sizeof(out));
	for (unsigned length=0; length<=129; length++) {
		if (length==128) continue;
		UT_ASSERT(!cluster_recovery_file_identity_decode_v2(data.bytes,length,&out));
		UT_ASSERT(memcmp(&out,&old,sizeof(out))==0);
		UT_ASSERT(!cluster_recovery_file_identity_encode_v2(&id,data.bytes,length));
		UT_ASSERT(memcmp(data.bytes,saved,sizeof(saved))==0);
	}
	UT_ASSERT(!cluster_recovery_file_identity_encode_v2(NULL,data.bytes,128));
	UT_ASSERT(!cluster_recovery_file_identity_encode_v2(&id,NULL,128));
	UT_ASSERT(!cluster_recovery_file_identity_decode_v2(NULL,128,&out));
	UT_ASSERT(!cluster_recovery_file_identity_decode_v2(data.bytes,128,NULL));
	UT_ASSERT(!cluster_recovery_file_identity_matches_v2(data.bytes,128,NULL));
}

int
main(void)
{
	UT_PLAN(8);
	UT_RUN(test_encode_matches_independent_bytes);
	UT_RUN(test_decode_preserves_every_field_without_struct_padding);
	UT_RUN(test_all_families_and_zero_origin_use_one_codec);
	UT_RUN(test_matches_checks_every_identity_field);
	UT_RUN(test_corruption_preserves_the_complete_output);
	UT_RUN(test_recomputed_crc_does_not_accept_malformed_identity);
	UT_RUN(test_invalid_encode_does_not_touch_destination);
	UT_RUN(test_aliases_and_wrong_lengths_preserve_inputs_and_outputs);
	UT_DONE();
	return ut_failed_count != 0;
}
